import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_runtime.h>
#define CONV_TILE_OH 16
#define CONV_TILE_OW 16
#define CONV_OC_CHUNK 16
#define CONV_TILE_D 4
#define CONV_THREADS 256
// Cooperative tiled direct convolution for the (K, K, 1) kernel shape.
// One CTA computes a 16x16 spatial output tile for one batch, a chunk of
// 16 output channels, and 4 adjacent depth slices.  Keeping 4 depth slices
// in the CTA makes the fastest-moving input/output dimension contiguous for
// the common stride-1 depth case and reuses the staged spatial halo/weights
// across those depth slices.
__global__ void conv3d_kk1_tiled_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N, int IC, int H, int W, int D,
    int OC, int HO, int WO, int DO,
    int sh, int sw, int sd,
    int ph, int pw, int pd,
    int dh, int dw,
    int K, int in_h, int in_w,
    int tiles_h, int tiles_w, int tiles_d, int oc_chunks,
    bool has_bias)
{
    long long bid = (long long)blockIdx.x;
    int oc_chunk = (int)(bid % oc_chunks); bid /= oc_chunks;
    int tile_w  = (int)(bid % tiles_w);   bid /= tiles_w;
    int tile_h  = (int)(bid % tiles_h);   bid /= tiles_h;
    int tile_d  = (int)(bid % tiles_d);   bid /= tiles_d;
    int n       = (int)bid;
    const int tid = threadIdx.x;
    const int ty = tid / CONV_TILE_OW;
    const int tx = tid % CONV_TILE_OW;
    const int oc0 = oc_chunk * CONV_OC_CHUNK;
    const int base_h = tile_h * CONV_TILE_OH * sh - ph;
    const int base_w = tile_w * CONV_TILE_OW * sw - pw;
    const int base_do = tile_d * CONV_TILE_D;
    extern __shared__ float smem[];
    float* sx = smem;
    float* swgt = sx + IC * in_h * in_w * CONV_TILE_D;
    const int total_in = IC * in_h * in_w * CONV_TILE_D;
    for (int e = tid; e < total_in; e += CONV_THREADS) {
        int dd = e % CONV_TILE_D;
        int t = e / CONV_TILE_D;
        int iw = t % in_w;
        t /= in_w;
        int ih = t % in_h;
        int ic = t / in_h;
        int hi = base_h + ih;
        int wi = base_w + iw;
        int do_ = base_do + dd;
        int di = do_ * sd - pd;
        float v = 0.0f;
        if (do_ < DO && di >= 0 && di < D && hi >= 0 && hi < H && wi >= 0 && wi < W) {
            long long xoff = ((((long long)n * IC + ic) * H + hi) * W + wi) * D + di;
            v = x[xoff];
        }
        sx[e] = v;
    }
    const int total_w = CONV_OC_CHUNK * IC * K * K;
    for (int e = tid; e < total_w; e += CONV_THREADS) {
        int j = e / (IC * K * K);
        int rem = e - j * (IC * K * K);
        int oc = oc0 + j;
        float v = 0.0f;
        if (oc < OC) {
            long long woff = ((((long long)oc * IC) * K) * K) + rem;
            v = w[woff];
        }
        swgt[e] = v;
    }
    __syncthreads();
    const int ho = tile_h * CONV_TILE_OH + ty;
    const int wo = tile_w * CONV_TILE_OW + tx;
    const bool out_valid = (ho < HO && wo < WO);
    float acc[CONV_OC_CHUNK][CONV_TILE_D];
    #pragma unroll
    for (int j = 0; j < CONV_OC_CHUNK; ++j) {
        int oc = oc0 + j;
        float b = (has_bias && oc < OC) ? bias[oc] : 0.0f;
        #pragma unroll
        for (int dd = 0; dd < CONV_TILE_D; ++dd) {
            acc[j][dd] = b;
        }
    }
    if (out_valid) {
        for (int ic = 0; ic < IC; ++ic) {
            for (int kh = 0; kh < K; ++kh) {
                int ly = ty * sh + kh * dh;
                for (int kw = 0; kw < K; ++kw) {
                    int lx = tx * sw + kw * dw;
                    const float4 xv = *reinterpret_cast<const float4*>(&sx[((ic * in_h + ly) * in_w + lx) * CONV_TILE_D]);
                    int wbase = (ic * K + kh) * K + kw;
                    #pragma unroll
                    for (int j = 0; j < CONV_OC_CHUNK; ++j) {
                        float wv = swgt[j * (IC * K * K) + wbase];
                        acc[j][0] = fmaf(xv.x, wv, acc[j][0]);
                        acc[j][1] = fmaf(xv.y, wv, acc[j][1]);
                        acc[j][2] = fmaf(xv.z, wv, acc[j][2]);
                        acc[j][3] = fmaf(xv.w, wv, acc[j][3]);
                    }
                }
            }
        }
    }
    if (out_valid) {
        #pragma unroll
        for (int j = 0; j < CONV_OC_CHUNK; ++j) {
            int oc = oc0 + j;
            if (oc < OC) {
                long long obase = ((((long long)n * OC + oc) * HO + ho) * WO + wo) * DO;
                #pragma unroll
                for (int dd = 0; dd < CONV_TILE_D; ++dd) {
                    int do_ = base_do + dd;
                    if (do_ < DO) {
                        out[obase + do_] = acc[j][dd];
                    }
                }
            }
        }
    }
}
// Generic fallback for configurations whose shared-memory tile would be
// too large or whose launch shape is outside the tiled kernel range.
__global__ void conv3d_kk1_kernel_generic(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N, int IC, int H, int W, int D,
    int OC, int HO, int WO, int DO,
    int sh, int sw, int sd,
    int ph, int pw, int pd,
    int dh, int dw,
    int K,
    bool has_bias)
{
    long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long total = (long long)N * OC * HO * WO * DO;
    if (idx >= total) return;
    int do_ = idx % DO;
    long long t = idx / DO;
    int wo = t % WO; t /= WO;
    int ho = t % HO; t /= HO;
    int oc = t % OC;
    int n  = (int)(t / OC);
    float sum = has_bias ? bias[oc] : 0.0f;
    int di = do_ * sd - pd;
    if (di >= 0 && di < D) {
        for (int ic = 0; ic < IC; ++ic) {
            for (int kh = 0; kh < K; ++kh) {
                int hi = ho * sh - ph + kh * dh;
                if (hi < 0 || hi >= H) continue;
                for (int kw = 0; kw < K; ++kw) {
                    int wi = wo * sw - pw + kw * dw;
                    if (wi < 0 || wi >= W) continue;
                    long long xoff = ((((long long)n * IC + ic) * H + hi) * W + wi) * D + di;
                    long long woff = ((((long long)oc * IC + ic) * K + kh) * K + kw);
                    sum = fmaf(x[xoff], w[woff], sum);
                }
            }
        }
    }
    out[idx] = sum;
}
torch::Tensor conv3d_forward(
    torch::Tensor x,
    torch::Tensor w,
    torch::Tensor bias,
    int64_t sh, int64_t sw,
    int64_t ph, int64_t pw,
    int64_t dh, int64_t dw,
    int64_t sd, int64_t pd)
{
    TORCH_CHECK(x.is_cuda() && w.is_cuda());
    TORCH_CHECK(x.dim() == 5 && w.dim() == 5);
    TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat);
    TORCH_CHECK(sh > 0 && sw > 0 && sd > 0 && dh > 0 && dw > 0);
    auto xc = x.contiguous();
    auto wc = w.contiguous();
    int N  = (int)xc.size(0);
    int IC = (int)xc.size(1);
    int H  = (int)xc.size(2);
    int W  = (int)xc.size(3);
    int D  = (int)xc.size(4);
    int OC = (int)wc.size(0);
    int K  = (int)wc.size(2);
    TORCH_CHECK((int)wc.size(1) == IC);
    TORCH_CHECK((int)wc.size(3) == K && (int)wc.size(4) == 1);
    int HO = (int)((H + 2 * ph - dh * (K - 1) - 1) / sh + 1);
    int WO = (int)((W + 2 * pw - dw * (K - 1) - 1) / sw + 1);
    int DO = (int)((D + 2 * pd - 1) / sd + 1);
    TORCH_CHECK(HO > 0 && WO > 0 && DO > 0);
    auto out = torch::empty({N, OC, HO, WO, DO}, xc.options());
    long long total = (long long)N * OC * HO * WO * DO;
    if (total == 0) return out;
    torch::Tensor bc;
    const float* bptr = nullptr;
    bool has_bias = bias.defined() && bias.numel() > 0;
    if (has_bias) {
        TORCH_CHECK(bias.numel() == OC);
        bc = bias.contiguous();
        bptr = bc.data_ptr<float>();
    }
    const float* xp = xc.data_ptr<float>();
    const float* wp = wc.data_ptr<float>();
    float* op = out.data_ptr<float>();
    auto stream = at::cuda::getCurrentCUDAStream();
    long long in_h_ll = (long long)(CONV_TILE_OH - 1) * sh + dh * (K - 1) + 1;
    long long in_w_ll = (long long)(CONV_TILE_OW - 1) * sw + dw * (K - 1) + 1;
    int tiles_h = (HO + CONV_TILE_OH - 1) / CONV_TILE_OH;
    int tiles_w = (WO + CONV_TILE_OW - 1) / CONV_TILE_OW;
    int tiles_d = (DO + CONV_TILE_D - 1) / CONV_TILE_D;
    int oc_chunks = (OC + CONV_OC_CHUNK - 1) / CONV_OC_CHUNK;
    bool use_tiled = false;
    int in_h = 0, in_w = 0;
    size_t smem_bytes = 0;
    long long tiled_blocks = 0;
    if (in_h_ll > 0 && in_w_ll > 0 && in_h_ll <= 4096 && in_w_ll <= 4096 && K <= 16) {
        in_h = (int)in_h_ll;
        in_w = (int)in_w_ll;
        smem_bytes = ((size_t)IC * (size_t)in_h * (size_t)in_w * (size_t)CONV_TILE_D +
                      (size_t)CONV_OC_CHUNK * (size_t)IC * (size_t)K * (size_t)K) * sizeof(float);
        tiled_blocks = (long long)N * tiles_d * tiles_h * tiles_w * oc_chunks;
        use_tiled = (smem_bytes <= 48 * 1024) && (tiled_blocks > 0) && (tiled_blocks <= 0x7fffffffLL);
    }
    if (use_tiled) {
        conv3d_kk1_tiled_kernel<<<(unsigned)tiled_blocks, CONV_THREADS, smem_bytes, stream>>>(
            xp, wp, bptr, op, N, IC, H, W, D, OC, HO, WO, DO,
            (int)sh, (int)sw, (int)sd, (int)ph, (int)pw, (int)pd,
            (int)dh, (int)dw, K, in_h, in_w, tiles_h, tiles_w, tiles_d, oc_chunks, has_bias);
    } else {
        int threads = 256;
        long long blocks = (total + threads - 1) / threads;
        conv3d_kk1_kernel_generic<<<(unsigned)blocks, threads, 0, stream>>>(
            xp, wp, bptr, op, N, IC, H, W, D, OC, HO, WO, DO,
            (int)sh, (int)sw, (int)sd, (int)ph, (int)pw, (int)pd,
            (int)dh, (int)dw, K, has_bias);
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
